package com.loopers.application.product;
import org.junit.jupiter.api.Test;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.test.context.jdbc.Sql;import java.util.*;import static org.assertj.core.api.Assertions.assertThat;
@SpringBootTest @Sql("classpath:week4/product-query-seed.sql") class ProductCacheFailureTest{@Autowired JdbcTemplate db;@Test void totalCacheFailureFallsBackToDb(){ProductCache down=new ProductCache(){public Optional<List<ProductQueryService.Result>> get(long b,int l){throw new IllegalStateException("redis down");}public void put(long b,int l,List<ProductQueryService.Result>v){throw new IllegalStateException("redis down");}public void evict(long b){throw new IllegalStateException("redis down");}};assertThat(new ProductQueryService(db,down).find(7,20)).hasSize(20);}}
